static inline void *kmalloc(size_t s, gfp_t gfp) /* <=== kmalloc */ 
{
	if (__kmalloc_fake)
		return __kmalloc_fake;
	return malloc(s);
}

static inline struct net *get_net(struct net *net) /* <=== get_net */ 
{
	return net;
}

static __inline__ int atomic_dec_return(atomic_t *v) /* <=== atomic_dec_return */ 
{
	unsigned long flags;
	int result;

	local_irq_save(flags);
	__asm__ __volatile__ (
		"# atomic_dec_return		\n\t"
		DCACHE_CLEAR("%0", "r4", "%1")
		M32R_LOCK" %0, @%1;		\n\t"
		"addi	%0, #-1;		\n\t"
		M32R_UNLOCK" %0, @%1;		\n\t"
		: "=&r" (result)
		: "r" (&v->counter)
		: "memory"
		__ATOMIC_CLOBBER
	);
	local_irq_restore(flags);

	return result;
}

static inline void __list_add(struct list_head *new, /* <=== __list_add */ 
			      struct list_head *prev,
			      struct list_head *next)
{
	next->prev = new;
	new->next = next;
	new->prev = prev;
	WRITE_ONCE(prev->next, new);
}

static inline int atomic_sub_return(int i, atomic_t *v) /* <=== atomic_sub_return */ 
{
	if (IS_21BIT_CONST(i))
		return __atomic_sub_return(i, v);

	return __atomic_add_return(-i, v);
}

static inline int atomic_dec_return(atomic_t *v) /* <=== atomic_dec_return */ 
{
	return __atomic_sub_return(1, &v->counter);
}

static inline void list_add(struct list_head *new, struct list_head *head) /* <=== list_add */ 
{
	__list_add(new, head, head->next);
}

static void ppp_destroy_channel(struct channel *pch) /* <=== ppp_destroy_channel */ 
{
	atomic_dec(&channel_count);

	if (!pch->file.dead) {
		/* "can't happen" */
		pr_err("ppp: destroying undead channel %p !\n", pch);
		return;
	}
	skb_queue_purge(&pch->file.xq);
	skb_queue_purge(&pch->file.rq);
	kfree(pch);
}

static inline void put_net(struct net *net) /* <=== put_net */ 
{
}

static void /* <=== init_ppp_file */ 
init_ppp_file(struct ppp_file *pf, int kind)
{
	pf->kind = kind;
	skb_queue_head_init(&pf->xq);
	skb_queue_head_init(&pf->rq);
	atomic_set(&pf->refcnt, 1);
	init_waitqueue_head(&pf->rwait);
}

static inline int atomic_sub_return(int i, atomic_t *v) /* <=== atomic_sub_return */ 
{
	return __atomic_sub_return(i, &v->counter);
}

static inline void *kzalloc(size_t s, gfp_t gfp) /* <=== kzalloc */ 
{
	void *p = kmalloc(s, gfp);

	memset(p, 0, s);
	return p;
}

static inline void list_add(struct list_head *new, struct list_head *head) /* <=== list_add */ 
{
	__list_add(new, head, head->next);
}

static inline void __list_add(struct list_head *new, /* <=== __list_add */ 
			      struct list_head *prev,
			      struct list_head *next)
{
	next->prev = new;
	new->next = next;
	new->prev = prev;
	prev->next = new;
}

static inline void *kzalloc(size_t size, gfp_t flags) /* <=== kzalloc */ 
{
	return kmalloc(size, flags | __GFP_ZERO);
}

static inline void atomic_dec(atomic_t *v) /* <=== atomic_dec */ 
{
	atomic_sub_return(1, v);
}

static inline void atomic_set(atomic_t *v, int i) /* <=== atomic_set */ 
{
	asm volatile(
		"	st	%1,%0\n"
		: "=Q" (v->counter) : "d" (i));
}

static inline void atomic_set(atomic_t *v, int i) /* <=== atomic_set */ 
{
	v->counter = i;
}

static inline void kfree(void *p) /* <=== kfree */ 
{
	if (p >= __kfree_ignore_start && p < __kfree_ignore_end)
		return;
	free(p);
}

static inline void atomic_dec(atomic_t *v) /* <=== atomic_dec */ 
{
	atomic_dec_return(v);
}

static __inline__ void atomic_set(atomic_t *v, int i) /* <=== atomic_set */ 
{
	unsigned long flags;
	_atomic_spin_lock_irqsave(v, flags);

	v->counter = i;

	_atomic_spin_unlock_irqrestore(v, flags);
}

static inline void atomic_set(atomic_t *v, int new) /* <=== atomic_set */ 
{
	asm volatile(
		"1:	r6 = memw_locked(%0);\n"
		"	memw_locked(%0,p0) = %1;\n"
		"	if (!P0) jump 1b;\n"
		:
		: "r" (&v->counter), "r" (new)
		: "memory", "p0", "r6"
	);
}

